1	/**
2	 * @module features/tv-dashboard/ui/TvColumnParts
3	 *
4	 * Blocos compartilhados das COLUNAS VERTICAIS da v3 (spec v3 — visão geral
5	 * `/tv`): chassi clicável com RAG, linha de última bipagem, perdas do
6	 * período, estoque crítico NOMEADO e mini-feed "AGORA". Usados por
7	 * `TvStoreColumn` (lojas) e `TvFabricaColumn` (fábrica).
8	 *
9	 * A coluna INTEIRA navega para `/tv/loja/:id` (acessível: role link +
10	 * Enter/Espaço). Cores fora da paleta sage só em desvio (âmbar/vermelho),
11	 * sempre com redundância ícone+texto.
12	 */
13	
14	import type { KeyboardEvent, ReactNode } from 'react';
15	import { useNavigate } from 'react-router-dom';
16	import {
17	  CheckCircle2,
18	  OctagonAlert,
19	  ScanLine,
20	  TriangleAlert,
21	} from 'lucide-react';
22	import type {
23	  TvCriticalItem,
24	  TvMarketingSummary,
25	  TvPerdasSummary,
26	  TvPeriod,
27	  TvRagStatus,
28	  TvRecentMove,
29	  TvStockAlertSummary,
30	} from '../model/types';
31	import {
32	  TV_CRITICAL_TOP_N,
33	  TV_MINI_FEED_SIZE,
34	  formatCompactBRL,
35	} from '../model/tvMath';
36	import {
37	  TV_PERIOD_LABEL,
38	  formatAgoLabel,
39	  formatQty,
40	  formatTimeHHMM,
41	  expectedPctNow,
42	  metaBarColorFromRatio,
43	} from './tvFormat';
44	
45	/** Borda + glow por estado RAG (sinal lível a 5m — mesma régua da v2). */
46	const COLUMN_RAG_FRAME: Record<TvRagStatus, string> = {
47	  ok: 'border border-[#57715B]/10 shadow-[0_8px_32px_rgba(0,0,0,0.06)]',
48	  amber: 'border-2 border-amber-400/60 shadow-[0_8px_32px_rgba(245,158,11,0.18)]',
49	  red: 'border-2 border-red-400/70 shadow-[0_8px_32px_rgba(229,72,77,0.15)]',
50	};
51	
52	/** Fundo semântico da coluna por RAG (aplicado sobre o bg-white/60 base). */
53	const COLUMN_RAG_BG: Record<TvRagStatus, string> = {
54	  ok: 'bg-white/60',
55	  amber: 'bg-amber-50/20',
56	  red: 'bg-red-50/40',
57	};
58	
59	/** Gradiente interno semântico por RAG (assinatura glass premium). */
60	const COLUMN_RAG_GRADIENT: Record<TvRagStatus, string> = {
61	  ok: 'bg-gradient-to-br from-white/40 via-transparent to-[#C5A065]/5',
62	  amber: 'bg-gradient-to-br from-white/40 via-transparent to-amber-400/5',
63	  red: 'bg-gradient-to-br from-white/40 via-transparent to-red-500/8',
64	};
65	
66	interface TvUnitColumnProps {
67	  lojaId: number;
68	  nome: string;
69	  rag: TvRagStatus;
70	  /** Hairline dourado de assinatura (fábrica). */
71	  goldHairline?: boolean;
72	  testId: string;
73	  children: ReactNode;
74	}
75	
76	/**
77	 * Chassi da coluna vertical: glass premium + frame RAG + clique/teclado
78	 * navegando para o drill-down `/tv/loja/:id`.
79	 */
80	export function TvUnitColumn({
81	  lojaId,
82	  nome,
83	  rag,
84	  goldHairline = false,
85	  testId,
86	  children,
87	}: TvUnitColumnProps) {
88	  const navigate = useNavigate();
89	  const open = () => navigate(`/tv/loja/${lojaId}`);
90	  const onKeyDown = (e: KeyboardEvent<HTMLElement>) => {
91	    if (e.key === 'Enter' || e.key === ' ') {
92	      e.preventDefault();
93	      open();
94	    }
95	  };
96	
97	  return (
98	    <section
99	      role="link"
100	      tabIndex={0}
101	      aria-label={`Abrir detalhes de ${nome}`}
102	      data-mia-action={`abrir-detalhe-loja-${lojaId}`}
103	      onClick={open}
104	      onKeyDown={onKeyDown}
105	      className={`relative flex flex-1 cursor-pointer flex-col overflow-hidden rounded-[2rem] p-3.5 backdrop-blur-xl saturate-150 transition-[border-color,box-shadow,background-color] [transition-duration:300ms] hover:bg-white/80 hover:shadow-[0_12px_40px_rgba(0,0,0,0.10)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#57715B]/40 motion-reduce:transition-none lg:p-4 ${COLUMN_RAG_FRAME[rag]} ${COLUMN_RAG_BG[rag]}`}
106	      data-testid={testId}
107	      data-rag={rag}
108	    >
109	      {/* Gradiente interno semântico por RAG (assinatura glass premium) */}
110	      <div
111	        className={`pointer-events-none absolute inset-0 ${COLUMN_RAG_GRADIENT[rag]}`}
112	        aria-hidden
113	      />
114	      {goldHairline && (
115	        <div className="absolute inset-x-0 top-0 h-0.5 bg-[#C5A065]/60" aria-hidden />
116	      )}
117	      <div className="relative z-10 flex h-full min-h-0 flex-col">{children}</div>
118	    </section>
119	  );
120	}
121	
122	/** Rótulo micro de seção dentro da coluna ("PERDAS · HOJE", "AGORA"…). */
123	export function TvColumnLabel({ children }: { children: ReactNode }) {
124	  return (
125	    <p className="font-momma text-[clamp(0.6875rem,0.75vw,1.375rem)] font-semibold uppercase tracking-wider text-[#5F6F63]">
126	      {children}
127	    </p>
128	  );
129	}
130	
131	/**
132	 * Linha de "pulso" da unidade: última bipagem com hora + "há X min".
133	 * Sem bipagem hoje → texto explícito (nunca campo em branco).
134	 */
135	export function TvColumnBipLine({
136	  ultimaBipagem,
137	  now,
138	}: {
139	  ultimaBipagem: string | null;
140	  now: Date;
141	}) {
142	  const time = formatTimeHHMM(ultimaBipagem);
143	  const ago = formatAgoLabel(ultimaBipagem, now);
144	  return (
145	    <p
146	      className="mt-0.5 flex items-center gap-1.5 font-momma text-[clamp(0.6875rem,0.8vw,1.5rem)] font-medium leading-tight text-[#7C887E]"
147	      data-testid="tv-col-bip"
148	    >
149	      <ScanLine className="h-[1em] w-[1em] shrink-0" aria-hidden />
150	      {time ? `bip ${time}${ago ? ` · ${ago}` : ''}` : 'sem bipagem hoje'}
151	    </p>
152	  );
153	}
154	
155	/**
156	 * Barra de meta FINA por coluna de loja: lógica idêntica ao hero, visual mais
157	 * compacto (h-1.5 lg:h-2) com label "XX% · esperado YY%" ao lado.
158	 */
159	export function TvColumnMetaBar({
160	  pctMetaProRata,
161	  metaDia,
162	  now,
163	}: {
164	  /** % pró-rata da meta do dia (pode ser null quando sem meta ou fora da janela). */
165	  pctMetaProRata: number | null;
166	  /** Meta do dia em R$ (null = sem meta cadastrada). */
167	  metaDia: number | null;
168	  now: Date;
169	}) {
170	  if (metaDia == null || metaDia <= 0) {
171	    return (
172	      <p className="mt-1 font-momma text-[clamp(0.6125rem,0.7vw,1.25rem)] text-[#7C887E]">
173	        sem meta
174	      </p>
175	    );
176	  }
177	
178	  const fillPct = pctMetaProRata;
179	  const expectedPct = expectedPctNow(now);
180	  const ratio =
181	    fillPct != null && expectedPct > 0 ? fillPct / expectedPct : null;
182	  const color = metaBarColorFromRatio(ratio, now);
183	
184	  return (
185	    <div className="mt-1.5 flex items-center gap-2" data-testid="tv-col-meta-bar">
186	      <div className="relative flex-1 rounded-full bg-[#57715B]/10 h-1.5 lg:h-2">
187	        {fillPct != null && (
188	          <div
189	            className={`absolute inset-y-0 left-0 rounded-full transition-[width] [transition-duration:600ms] ease-out motion-reduce:transition-none ${
190	              color === 'sage'
191	                ? 'bg-gradient-to-r from-[#57715B] to-[#4a6250]'
192	                : color === 'amber'
193	                  ? 'bg-gradient-to-r from-amber-400 to-amber-500'
194	                  : 'bg-gradient-to-r from-red-400 to-red-500'
195	            }`}
196	            style={{ width: `${Math.max(0, Math.min(100, fillPct))}%` }}
197	          />
198	        )}
199	        {expectedPct > 0 && (
200	          <div
201	            className="absolute rounded-full bg-[#C5A065]"
202	            style={{
203	              left: `calc(${Math.max(0, Math.min(100, expectedPct))}% - 1px)`,
204	              top: -3,
205	              width: 2,
206	              height: 14,
207	            }}
208	          />
209	        )}
210	      </div>
211	      <p className="shrink-0 font-momma text-[clamp(0.6125rem,0.7vw,1.25rem)] tabular-nums text-[#7C887E]">
212	        {fillPct != null ? `${Math.round(fillPct)}%` : '—'}
213	        {' · esp. '}
214	        {expectedPct}%
215	      </p>
216	    </div>
217	  );
218	}
