151	/** Strip do mês (R3+R4): MTD, meta mensal, meta da semana e projeção. */
152	function TvHeroMonthStrip({
153	  monthProgress,
154	  now,
155	}: {
156	  monthProgress: TvMonthProgress;
157	  now: Date;
158	}) {
159	  const { mtdTotal, metaMensal, pctMeta, currentWeek, projection } =
160	    monthProgress;
161	
162	  // % do mês decorrido (tick de "esperado agora" da barra mensal)
163	  const daysInMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0).getDate();
164	  const expectedMonthPct = Math.round((now.getDate() / daysInMonth) * 100);
165	  const monthRatio =
166	    pctMeta != null && expectedMonthPct > 0 ? pctMeta / expectedMonthPct : null;
167	  const monthBarColor = metaBarColorFromRatio(monthRatio, now);
168	
169	  // Meta da semana corrente (target redistribuído × realizado).
170	  // COR pace-adjusted como a mensal acima: ratio = %real / %esperado-agora
171	  // (dias decorridos ÷ dias do segmento, hoje contando inteiro) — começo
172	  // de semana no ritmo não fica vermelho. O % NUMÉRICO exibido é o real.
173	  const weekPct =
174	    currentWeek && currentWeek.target > 0
175	      ? ((currentWeek.achieved ?? 0) / currentWeek.target) * 100
176	      : null;
177	  const expectedWeekPct = Math.round(expectedWeekFraction(now) * 100);
178	  const weekColor = metaBarColorFromRatio(
179	    weekPct != null && expectedWeekPct > 0 ? weekPct / expectedWeekPct : null,
180	    now,
181	  );
182	
183	  const labelCls =
184	    'font-momma text-[clamp(0.6875rem,0.85vw,1.625rem)] font-semibold uppercase tracking-wider text-[#5F6F63]';
185	  const valueCls =
186	    'mt-1 font-momma text-[clamp(1.25rem,1.8vw,3.25rem)] font-bold leading-none text-[#2D362E] tabular-nums';
187	
188	  return (
189	    <div
190	      className="grid grid-cols-2 items-start gap-x-4 gap-y-4 border-t border-[#57715B]/10 pt-4 lg:grid-cols-4 lg:gap-8"
191	      data-testid="tv-hero-month-strip"
192	    >
193	      {/* Mês até agora (MTD da rede) */}
194	      <div className="min-w-0">
195	        <span className={labelCls}>MÊS ATÉ AGORA</span>
196	        <p className={valueCls} data-testid="tv-hero-mtd">
197	          {formatCompactBRL(mtdTotal)}
198	        </p>
199	      </div>
200	
201	      {/* % da meta mensal + mini barra (oculto sem meta cadastrada) */}
202	      {metaMensal != null && pctMeta != null ? (
203	        <div className="min-w-0" data-testid="tv-hero-month-goal">
204	          <span className={labelCls}>META MENSAL</span>
205	          <p className={valueCls}>
206	            {Math.round(pctMeta)}%
207	            <span className="font-momma text-[clamp(0.75rem,0.9vw,1.625rem)] font-normal text-[#7C887E]">
208	              {' '}
209	              de {formatCompactBRL(metaMensal)}
210	            </span>
211	          </p>
212	          <div className="mt-2 max-w-[18rem]">
213	            <TvMetaBar
214	              fillPct={pctMeta}
215	              expectedPct={expectedMonthPct}
216	              color={monthBarColor}
217	              size="card"
218	            />
219	          </div>
220	        </div>
221	      ) : (
222	        <div className="min-w-0" aria-hidden />
223	      )}
224	
225	      {/* Meta da semana corrente (redistribuída — R4) */}
226	      {currentWeek && (
227	        <div className="min-w-0" data-testid="tv-hero-week-goal">
228	          <span className={labelCls}>META DA SEMANA</span>
229	          <p className={valueCls}>
230	            {formatCompactBRL(currentWeek.achieved ?? 0)}
231	            <span className="font-momma text-[clamp(0.75rem,0.9vw,1.625rem)] font-normal text-[#7C887E]">
232	              {' '}
233	              / {formatCompactBRL(currentWeek.target)}
234	            </span>
235	          </p>
236	          {weekPct != null && (
237	            <p
238	              className={`mt-1 font-momma text-[clamp(0.6875rem,0.8vw,1.5rem)] font-semibold tabular-nums ${WEEK_PCT_TEXT_CLS[weekColor]}`}
239	            >
240	              {Math.round(weekPct)}% da semana
241	            </p>
242	          )}
243	        </div>
244	      )}
245	
246	      {/* Projeção de fim de mês (run-rate — R3) */}
247	      <div className="min-w-0">
248	        <span className={labelCls}>PROJEÇÃO DO MÊS</span>
249	        <p className={valueCls} data-testid="tv-hero-projection">
250	          {formatCompactBRL(projection)}
251	        </p>
252	      </div>
253	    </div>
254	  );
255	}
