1	/**
2	 * @module features/tv-dashboard/ui/TvStoreColumn
3	 *
4	 * Coluna vertical de loja — redesign baseado em research de TV dashboards
5	 * (Bach et al. IEEE TVCG 2023 + practitioner evidence):
6	 * - Número de vendas é o sinal primário → domina o espaço visualmente
7	 * - Máximo 5 elementos por card para não causar cognitive overload
8	 * - 1 RAG status por card (não 15 células coloridas)
9	 * - Detalhe de perdas/marketing/estoque → drill-down /tv/loja/:id
10	 */
11	
12	import { useEffect, useRef, useState } from 'react';
13	import { Bike } from 'lucide-react';
14	import type { TvFreshnessLevel, TvPeriod, TvStoreData } from '../model/types';
15	import {
16	  expectedWeekFraction,
17	  formatCompactBRL,
18	  parseBrDateTime,
19	  parseIsoDateLocal,
20	} from '../model/tvMath';
21	import { TvDeltaChip, TvLiveIndicator, TvMetaBar, TvRankChip, TvStateChip } from './TvChips';
22	import {
23	  TvColumnBipLine,
24	  TvColumnMetaBar,
25	  TvColumnStockLine,
26	  TvUnitColumn,
27	} from './TvColumnParts';
28	import {
29	  formatTicketBRL,
30	  formatWeekdayDayMonth,
31	  metaBarColorFromRatio,
32	  type TvBarColor,
33	} from './tvFormat';
34	import { useCountUp } from './useCountUp';
35	
36	interface TvStoreColumnProps {
37	  store: TvStoreData;
38	  liveLevel: TvFreshnessLevel;
39	  period: TvPeriod;
40	  now: Date;
41	  rank?: number | null;
42	}
43	
44	/** Coluna de loja — canal Degust live ou Linx defasado. */
45	export function TvStoreColumn({ store, liveLevel, period, now, rank }: TvStoreColumnProps) {
46	  const { vendas, channel } = store;
47	  const isLive = channel === 'degust-live';
48	  const valorAnim = useCountUp(vendas?.valor ?? 0);
49	  const refDate = vendas ? parseIsoDateLocal(vendas.dataReferencia) : null;
50	
51	  // Flash dourado ao atualizar o valor de venda
52	  const prevValueRef = useRef(vendas?.valor);
53	  const [flashing, setFlashing] = useState(false);
54	  const flashKeyRef = useRef(0);
55	  useEffect(() => {
56	    if (
57	      vendas?.valor != null &&
58	      prevValueRef.current != null &&
59	      vendas.valor !== prevValueRef.current
60	    ) {
61	      flashKeyRef.current += 1;
62	      setFlashing(true);
63	      const t = window.setTimeout(() => setFlashing(false), 450);
64	      prevValueRef.current = vendas.valor;
65	      return () => window.clearTimeout(t);
66	    }
67	    prevValueRef.current = vendas?.valor;
68	  }, [vendas?.valor]);
69	
70	  // Linha de status: fonte + horário de atualização
71	  const updateTime = isLive ? parseBrDateTime(vendas?.atualizadoEm) : null;
72	  const laggedLabel = !isLive && refDate ? formatWeekdayDayMonth(refDate) : null;
73	
74	  const showRank = rank != null && rank >= 1 && rank <= 3;
75	
76	  return (
77	    <TvUnitColumn lojaId={store.lojaId} nome={store.nome} rag={store.rag} testId="tv-store-column">
78	
79	      {/* Header: nome + chips de status */}
80	      <div className="flex items-start justify-between gap-2">
81	        <h2 className="min-w-0 font-momma text-sm font-semibold leading-tight text-[#5F6F63] truncate">
82	          {store.nome.replace(/^Momma\s+/i, '')}
83	        </h2>
84	        <div className="flex shrink-0 items-center gap-1">
85	          {showRank && <TvRankChip rank={rank as 1 | 2 | 3} />}
86	          <TvStateChip rag={store.rag} />
87	        </div>
88	      </div>
89	
90	      {/* Número de vendas + setinhas inline — exatamente como na v2 */}
91	      <div className="mt-2 flex flex-wrap items-end gap-x-2 gap-y-1">
92	        <span
93	          key={flashing ? `flash-${flashKeyRef.current}` : 'static'}
94	          className={`font-momma text-3xl font-bold leading-none tabular-nums sm:text-4xl ${
95	            vendas ? 'text-[#2D362E]' : 'text-[#9ca3af]'
96	          }${flashing ? ' tv-value-flash' : ''}`}
97	          data-testid="tv-store-sales"
98	        >
99	          {vendas ? formatCompactBRL(valorAnim) : '—'}
100	        </span>
101	        {store.deltaOntem != null && (
102	          <TvDeltaChip delta={store.deltaOntem} label={isLive ? 'ontem' : 'dia ant.'} size="card" />
103	        )}
104	        {store.deltaSemana != null && period === 'week' && (
105	          <TvDeltaChip delta={store.deltaSemana} label="sem. ant." size="card" />
106	        )}
107	      </div>
108	
109	      {/* R1: quebra Loja × Delivery (só BSB Shopping, período "hoje") —
110	          o número principal acima segue sendo o TOTAL oficial */}
111	      {store.deliverySplit && (
112	        <p
113	          className="mt-1 flex flex-wrap items-center gap-x-1.5 gap-y-0 text-xs tabular-nums text-[#7C887E]"
114	          data-testid="tv-delivery-split"
115	        >
116	          <span className="whitespace-nowrap">
117	            Loja{' '}
118	            <span className="font-medium text-[#5F6F63]">
119	              {formatCompactBRL(store.deliverySplit.balcao)}
120	            </span>
121	          </span>
122	          <span aria-hidden>·</span>
123	          <span className="inline-flex items-center gap-1 whitespace-nowrap">
124	            <Bike className="h-3 w-3 shrink-0 text-[#57715B]" aria-hidden />
125	            Delivery{' '}
126	            <span className="font-medium text-[#5F6F63]">
127	              {formatCompactBRL(store.deliverySplit.delivery)}
128	            </span>
129	          </span>
130	        </p>
131	      )}
132	
133	      {/* Status de fonte — compacto, sem "ao vivo" como texto */}
134	      <p className="mt-1 flex items-center gap-1.5 text-xs text-[#9ca3af]">
135	        <TvLiveIndicator channel={channel} liveLevel={liveLevel} />
136	        {isLive
137	          ? updateTime
138	            ? `${updateTime.getHours().toString().padStart(2, '0')}:${updateTime.getMinutes().toString().padStart(2, '0')}`
139	            : 'hoje'
140	          : laggedLabel ?? 'sem dados'}
141	      </p>
142	
143	      {/* Barra de meta do DIA */}
144	      <TvColumnMetaBar pctMetaProRata={store.pctMeta} metaDia={store.metaDia} now={now} />
145	
146	      {/* Meta da SEMANA corrente (seg–dom) — linha secundária, não compete
147	          com o número grande de vendas do dia. Ausente quando a loja não
148	          tem meta mensal cadastrada (weeklyGoal null/undefined). */}
149	      {store.weeklyGoal && (
150	        <TvStoreWeeklyGoalLine weeklyGoal={store.weeklyGoal} now={now} />
151	      )}
152	
153	      {/* Nº de vendas + R$/venda — cada parte non-breaking para não cortar */}
154	      {isLive && (vendas?.cupons != null || vendas?.ticketMedio != null) && (
155	        <div className="mt-2 flex flex-wrap items-baseline gap-x-1.5 gap-y-0 text-xs tabular-nums text-[#7C887E]">
156	          {vendas?.cupons != null && (
157	            <span className="whitespace-nowrap font-medium">
158	              {vendas.cupons} vendas
159	            </span>
160	          )}
161	          {vendas?.ticketMedio != null && vendas.ticketMedio > 0 && (
162	            <span className="whitespace-nowrap">
163	              {vendas.cupons != null && '· '}
164	              <span className="font-medium">{formatTicketBRL(vendas.ticketMedio)}</span>
165	              <span>/venda</span>
166	            </span>
167	          )}
168	        </div>
169	      )}
170	
171	      {/* Bip + Status de estoque — 1 linha para cada */}
172	      <div className="mt-auto pt-3 space-y-1">
173	        <TvColumnBipLine ultimaBipagem={store.movimentacao.ultimaBipagem} now={now} />
174	        <TvColumnStockLine estoque={store.estoque} />
175	      </div>
176	    </TvUnitColumn>
177	  );
178	}
179	
180	/** Cor do % da semana: emerald quando batida; senão mesma régua da barra. */
181	const WEEKLY_PCT_CLS: Record<TvBarColor, string> = {
182	  sage: 'text-[#57715B]',
183	  amber: 'text-amber-600',
184	  red: 'text-red-600',
185	};
186	
187	/**
188	 * Linha SECUNDÁRIA de meta semanal do card: label "SEMANA" + % em destaque
189	 * (cor pace-adjusted pela mesma régua da diária/mensal; emerald quando
190	 * ≥ 100%) + valores compactos "R$ X / R$ Y" + mini barra de progresso
191	 * ({@link TvMetaBar} mini com tick dourado no esperado-agora da semana).
192	 *
193	 * COR pace-adjusted: ratio = %real / %esperado-agora, com esperado =
194	 * dias decorridos ÷ dias do segmento seg-dom corrente do mês
195	 * ({@link expectedWeekFraction} — derivado localmente porque o
196	 * `weeklyGoal` do model não expõe o segmento). Começo de semana no ritmo
197	 * NÃO fica vermelho. O % NUMÉRICO exibido segue sendo o real.
198	 */
199	function TvStoreWeeklyGoalLine({
200	  weeklyGoal,
201	  now,
202	}: {
203	  weeklyGoal: NonNullable<TvStoreData['weeklyGoal']>;
204	  now: Date;
205	}) {
206	  const { target, achieved, pct } = weeklyGoal;
207	  const beaten = pct != null && pct >= 100;
208	  const expectedWeekPct = Math.round(expectedWeekFraction(now) * 100);
209	  const barColor: TvBarColor = beaten
210	    ? 'sage'
211	    : metaBarColorFromRatio(
212	        pct != null && expectedWeekPct > 0 ? pct / expectedWeekPct : null,
213	        now,
214	      );
215	  const pctCls = beaten ? 'text-emerald-600' : WEEKLY_PCT_CLS[barColor];
216	
217	  return (
218	    <div className="mt-2" data-testid="tv-weekly-goal">
219	      <div className="flex flex-wrap items-baseline justify-between gap-x-2 gap-y-0.5">
220	        <span className="font-momma text-[10px] font-semibold uppercase tracking-wider text-[#7C887E]">
221	          SEMANA
222	        </span>
223	        <span className="min-w-0 truncate text-right font-momma text-[10px] tabular-nums text-[#9ca3af]">
224	          <span
225	            className={`text-xs font-bold tabular-nums ${pctCls}`}
226	            data-testid="tv-weekly-goal-pct"
227	          >
228	            {pct != null ? `${Math.round(pct)}%` : '—'}
229	          </span>{' '}
230	          {formatCompactBRL(achieved)} / {formatCompactBRL(target)}
231	        </span>
232	      </div>
233	      <div className="mt-1">
234	        <TvMetaBar
235	          fillPct={pct}
236	          expectedPct={pct != null ? expectedWeekPct : null}
237	          color={barColor}
238	          size="mini"
239	        />
240	      </div>
241	    </div>
242	  );
243	}
