1	/**
2	 * @module features/tv-dashboard/model/useTvReport
3	 *
4	 * Dados do RELATÓRIO MATINAL (R6 da spec `tv-acompanhamento-live`):
5	 * uma única chamada à edge `degust-pos-financial` cobrindo o mês do
6	 * dia-base (01 → dia-base, com quebra delivery do BSB) + `metas_mensais`
7	 * do mês. Deriva: faturamento do dia-base por loja e rede, MTD por loja
8	 * e rede, meta mensal + %, meta/realizado da semana corrente
9	 * (redistribuição de `weeklyTargets`) e projeção de fim de mês.
10	 *
11	 * SEM polling: o relatório é um snapshot sob demanda (modal aberto).
12	 * `buildTvReportText` é pura — testável sem I/O.
13	 */
14	
15	import { useQuery, useQueryClient, type QueryClient } from '@tanstack/react-query';
16	import { supabase } from '@/integrations/supabase/client';
17	import {
18	  TV_DELIVERY_SPLIT_LOJA_ID,
19	  monthEndProjection,
20	  parseIsoDateLocal,
21	  toIsoDateLocal,
22	  weeklyTargets,
23	} from './tvMath';
24	import type { TvWeeklyGoal } from './types';
25	import {
26	  TV_QUERY_INTERVALS,
27	  fetchTvContext,
28	  tvDashboardKeys,
29	} from './useTvDashboardData';
