31	// ─────────────────────────────────────────────────────────────────────────────
32	// Tipos
33	// ─────────────────────────────────────────────────────────────────────────────
34	
35	/** Linha por loja do relatório (dia-base + acumulado do mês). */
36	export interface TvReportLojaLine {
37	  lojaId: number;
38	  /** Nome curto (sem o prefixo "Momma "). */
39	  nome: string;
40	  /** R$ do dia-base (null = sem venda registrada no dia → "—"). */
41	  valorDia: number | null;
42	  /** R$ acumulado 01 → dia-base. */
43	  mtd: number;
44	}
45	
46	/** Snapshot derivado do relatório matinal. */
47	export interface TvReportData {
48	  /** Dia-base (YYYY-MM-DD). */
49	  baseDate: string;
50	  /** R$ da rede no dia-base. */
51	  totalDia: number;
52	  /** R$ da rede acumulado 01 → dia-base. */
53	  totalMtd: number;
54	  /** Lojas Degust ordenadas por faturamento do dia desc (sem venda no fim). */
55	  lojas: TvReportLojaLine[];
56	  /** Quebra do BSB Shopping no dia-base (null sem cupom delivery). */
57	  deliverySplit: { delivery: number; balcao: number } | null;
58	  /** Meta mensal da rede (linha NULL; fallback soma por loja), ou null. */
59	  metaMensal: number | null;
60	  /** % da meta mensal já realizada, ou null sem meta. */
61	  pctMeta: number | null;
62	  /** Semana corrente (contendo o dia-base) com meta redistribuída, ou null. */
63	  currentWeek: TvWeeklyGoal | null;
64	  /** Projeção de fim de mês por run-rate até o dia-base. */
65	  projection: number;
66	}
67	
68	/** Resposta da edge `degust-pos-financial` (campos usados no relatório). */
69	interface DegustReportResponse {
70	  daily?: Array<{
71	    data: string;
72	    loja_id: number;
73	    total_faturado: number;
74	    total_cupons: number;
75	  }>;
76	  deliverySplit?: Array<{
77	    data: string;
78	    loja_id: number;
79	    total_delivery: number;
80	    cupons_delivery: number;
81	  }>;
82	}
